type Facts = Record<string, Fact>;
function c(
  id: string,
  facts: Facts,
  predicate: (f: Facts) => boolean,
  cause: string,
  evidence: string,
  requirement: string,
  repair: string,
  diagnostic: string,
  falsifier: string,
): FormalCase {
  const minimums: Record<string, 'Middle' | 'Senior'> = {
    'expired-provider-key': 'Middle',
    'no-status-contract': 'Middle',
    'old-writer-after-backfill': 'Middle',
    'contract-before-rollback': 'Senior',
    'rollback-schema-gap': 'Senior',
    'replay-reader-removed': 'Middle',
    'epoch-reuse': 'Middle',
    'check-before-effect': 'Middle',
    'cohort-failure': 'Middle',
  };
  return {
    id,
    facts,
    predicate,
    hazard: id,
    invariant: `Требуется ${requirement}.`,
    cause,
    evidence,
    requirements: [requirement],
    repair,
    diagnostic,
    falsifier,
    ...(minimums[id] ? { minimumGrade: minimums[id] } : {}),
  };
}
function model(
  id: string,
  title: string,
  siblingGroup: string,
  tags: string[],
  measuredDimensions: CompetencyDimension[],
  topology: string[],
  introduction: string,
  cases: FormalCase[],
  code?: (w: WorldState) => string,
): ItemModel {
  const measured = [
    ...new Set([
      ...measuredDimensions,
      ...(measuredDimensions.includes('diagnosis') ? (['engineering_judgment'] as const) : []),
      ...(measuredDimensions.includes('adaptation') ? (['correctness'] as const) : []),
    ]),
  ];
  return {
    id,
    title,
    siblingGroup,
    contentTags: tags,
    measuredDimensions: measured,
    topology,
    introduction,
    cases,
    version: '2.0.1',
    specialization: 'backend',
    stages: [
      'anchors',
      ...(measured.includes('diagnosis') ? (['incident'] as const) : []),
      ...(measured.includes('adaptation') ? (['review'] as const) : []),
      'boundary',
    ],
    radicalDefinitions: [
      { name: 'failure', affects: 'Причина, нарушенный инвариант и допустимое исправление' },
      { name: 'workers', affects: 'Параллельность исполнения' },
      { name: 'legacyClients', affects: 'Совместимость изменений' },
      { name: 'rollbackRequired', affects: 'Обратимость исправления' },
      { name: 'observability', affects: 'Число источников и связывание событий' },
      ...[...new Set(cases.flatMap((c) => Object.keys(c.facts)))].map((name) => ({
        name: `failure.${name}`,
        affects: 'Формальная причина или предположение, определяющее допустимое решение',
      })),
    ],
    incidentalDefinitions: [
      'domain',
      'service',
      'entity',
      'table',
      'endpoint',
      'operationId',
      'timestamp',
      'rps',
      'timeoutSeconds',
      'wording',
    ],
    misconceptionClasses: [
      'insufficient_observability',
      'wrong_causal_layer',
      'incorrect_consistency_assumption',
      'local_fix_for_distributed_problem',
      'unsafe_migration_order',
    ],
    code: code || ((w) => renderGeneratedCode(id, title, w)),
  };
}
