function pack(
  id: string,
  name: string,
  itemModels: ItemModel[],
  enabled = true,
): SpecializationPack {
  return {
    id,
    name,
    enabled,
    itemModels: itemModels
      .map(applyContentPolicy)
      .map((model) => (id === 'backend' ? withBackendContexts(model) : model)),
    version: id === 'backend' ? '5.0.0' : '3.0.0',
    competencyBlueprint: [...dimensions],
    artifactGenerators: [
      'architecture',
      'code',
      'diff',
      'logs',
      'metrics',
      'trace',
      'db',
      'queue',
      'network',
      'deployment',
      'table',
      'chart',
      ...(id === 'frontend' ? (['console', 'browser_state'] as const) : []),
    ],
    renderers: ['ru-compositional-v2'],
    misconceptionCatalog: [...new Set(itemModels.flatMap((m) => m.misconceptionClasses))],
    worldBounds,
    ...(id === 'backend'
      ? { validateBalance: validateDomainCoverage, coreDomainCounts: backendDomainCounts }
      : {}),
  };
}
export const packs: SpecializationPack[] = [
  pack('backend', 'Backend', [...backend, ...localBackendModels]),
  attachExecutableSamples(buildProfessionalPack(frontendDefinition)),
  attachExecutableSamples(buildProfessionalPack(sreDefinition)),
  ...[
    qaDefinition,
    dataDefinition,
    mlEngineerDefinition,
    dataScientistDefinition,
    mlopsDefinition,
    genaiDefinition,
    androidDefinition,
    iosDefinition,
    securityDefinition,
  ].map((definition) =>
    attachExecutableSamples(
      buildProfessionalPack({
        ...definition,
        models: [
          ...definition.models,
          ...(definition.id === 'qa-automation'
            ? [qaLayerContract]
            : definition.id === 'ml-engineer'
              ? [mlCandidateGate]
              : definition.id === 'data-scientist'
                ? [dsClaimBoundary]
                : []),
        ],
      }),
    ),
  ),
  pack('data-ml', 'Data / ML', [], false),
].map(withPackGradeModel);
/** Pack registration requires no changes to the adaptive runtime. */
export function getPack(id: string): SpecializationPack {
  const found = packs.find((p) => p.id === id && p.enabled);
  if (!found) throw new Error('Для выбранной специализации нет опубликованного generative pack');
  return found;
}
export function getItemModel(packId: string, modelId: string): ItemModel {
  const found =
    getPack(packId).itemModels.find((m) => m.id === modelId) ||
    (packId === 'frontend' ? frontend : packId === 'devops-sre' ? sre : [])
      .map(applyContentPolicy)
      .find((m) => m.id === modelId);
  if (!found) throw new Error('ItemModel не найден');
  return found;
}
